<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');
 if($action==='add_admin'){
  $name=trim((string)($_POST['name']??''));$username=trim((string)($_POST['username']??''));$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');
  if($name===''||text_len($name)>80||!valid_username($username)||username_exists($username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12){flash('error','Enter a valid name/email and a password with at least 12 characters.');}
  else{$check=db()->prepare('SELECT id FROM users WHERE email=:e');$check->execute([':e'=>$email]);if($check->fetchColumn())flash('error','That email address is already registered.');else{db()->prepare("INSERT INTO users(name,username,email,password_hash,role) VALUES(:n,:u,:e,:p,'admin')")->execute([':n'=>$name,':u'=>$username,':e'=>$email,':p'=>password_hash($password,PASSWORD_DEFAULT)]);flash('success','Administrator account created. Share the credentials securely.');}}
  redirect(app_path('admin/users.php'));
 }
 if($id!==(int)$_SESSION['admin_id']&&in_array($action,['activate','suspend'],true)){
  db()->prepare("UPDATE users SET is_active=:v WHERE id=:id AND role<>'admin'")->execute([':v'=>$action==='activate'?1:0,':id'=>$id]);flash('success',$action==='activate'?'Member account activated.':'Member account suspended.');
 }
 redirect(app_path('admin/users.php'));
}
$q=trim((string)($_GET['q']??''));$role=(string)($_GET['role']??'all');$where=[];$params=[];if($q!==''){$where[]='(name LIKE :q OR username LIKE :q OR email LIKE :q)';$params[':q']='%'.$q.'%';}if(in_array($role,['member','owner','admin'],true)){$where[]='role=:role';$params[':role']=$role;}$sql='SELECT id,name,username,email,role,is_active,created_at FROM users'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC LIMIT 200';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$adminTitle='Members & accounts';include __DIR__.'/_header.php';?>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">ADMINISTRATOR ACCESS</span><h2>Add another administrator</h2></div></div><form method="post" class="studio-fields"><?= csrf_field() ?><input type="hidden" name="action" value="add_admin"><div class="form-grid"><label>Name<input name="name" required maxlength="80"></label><label>Username<input name="username" minlength="3" maxlength="30" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label></div><button class="button button-primary">Create admin account</button></form><p class="form-footnote">Only create administrator accounts for trusted team members. Use unique passwords and do not share credentials in chat.</p></div>
<div class="admin-panel"><form class="admin-filter" method="get"><input type="search" name="q" value="<?= h($q) ?>" placeholder="Search name, username or email"><select name="role"><option value="all">All roles</option><?php foreach(['member','owner','admin'] as $r): ?><option value="<?= $r ?>" <?= $role===$r?'selected':'' ?>><?= ucfirst($r) ?></option><?php endforeach; ?></select><button class="button button-dark button-small">Filter</button></form><div class="table-wrap"><table class="admin-table"><thead><tr><th>Member</th><th>Role</th><th>Joined</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= h($r['name']) ?></strong><small>@<?= h($r['username']) ?> · <?= h($r['email']) ?></small></td><td><?= h(ucfirst($r['role'])) ?></td><td><?= h(format_date($r['created_at'])) ?></td><td><span class="status-pill <?= (int)$r['is_active']?'status-approved':'status-rejected' ?>"><?= (int)$r['is_active']?'Active':'Suspended' ?></span></td><td><?php if($r['role']!=='admin'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="<?= (int)$r['is_active']?'suspend':'activate' ?>"><button class="table-action"><?= (int)$r['is_active']?'Suspend':'Activate' ?></button></form><?php else: ?><small>Administrator</small><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="empty-admin">No accounts found.</td></tr><?php endif; ?></tbody></table></div><p class="form-footnote">Administrator accounts cannot be suspended from this screen. Owner privileges are granted only through an approved business ownership claim. This page does not provide password resets.</p></div><?php include __DIR__.'/_footer.php';?>
